local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["f105a9edcefad48d"] = { "Le ali di %s rombano in lontananza.", "." },
  ["f1082cbfe9cfc5a6"] = { "Voi no sfidare me, pivelli! Io essere re adesso, e io restare re PER SEMPRE!!!", "." },
  ["f10ad4465595f44f"] = { "Bentornat<o/a>, {name}. Che cosa aveva da dire Wiley a sua discolpa?", "." },
  ["f10d9e00a78df129"] = { "Quel Lumak... sempre a pescare invece di combattere. Lo troverai sul suo pontile sul lago, nella ⟦Valley of Honor=Valle dell'Onore⟧. Già che ci sei, saluta Shankys da parte mia.", "." },
  ["f112d04bfd8f46e8"] = { "Accidenti! Quello laggiù nella ⟦The Maul=Fossa Infausta⟧ è Mushgog.", "." },
  ["f11501bc84d5f216"] = { "Mi arrivano continuamente rapporti sulle tue imprese contro l'Abyssal Council, {name}. Stai facendo grandi cose là fuori!\n\nContinua così, e faremo in modo che ne valga la pena!", "." },
  ["f116ec608a8b8909"] = { "Cosa? No, non riparo armature. ⟦Everlook=Lungavista⟧ è circa un miglio più a nord, <fratello/sorella>.\n\nOra compra qualcosa, o sparisci prima che chiami il mio stregone a occuparsi di te!", "." },
  ["f11c8f2e8ff386b7"] = { "Gli studi di magia ti stanno spremendo il cervello? Rilassati al Blue Recluse!", "." },
  ["f11dc9e597ba4145"] = { "Perché non hai semplicemente tagliato la corda?", "." },
  ["f11e9e9c98a26e05"] = { "Siamo stati traditi!", "." },
  ["f11eef2519ebf3bd"] = { "Salute, amico, un momento del tuo tempo, se posso...\n\nAbbiamo sopportato molte prove e tribolazioni per fondare Teldrassil. Come se i continui conflitti di questi tempi non bastassero, ora ci troviamo a corto di stoffa. Se hai materiali da parte, ti chiedo di donarli. Aiutandoci ti guadagneresti di certo la gratitudine degli elfi della notte di ogni dove!", "." },
  ["f12d34de3f3e7955"] = { "Alimentazione di emergenza attivata! Avvio del motore deambulatorio! COCCODÈ!", "." },
  ["f130f0078354318b"] = { "Oh, cerchi un po' di illuminazione arcana, vero? Non c'è posto migliore del Wizard's Sanctum nel ⟦Mage Quarter=Quartiere dei Maghi⟧.", "." },
  ["f1351533c1e30521"] = { "Vedi, tutto quello che devi fare è forgiare il Martello di Sulfuron e trovare l'⟦Eye of Sulfuras=Occhio di Sulfuras⟧. Unisci l'⟦Eye of Sulfuras=Occhio di Sulfuras⟧ al Martello di Sulfuron e diventerà Sulfuras! Ora, non ti tedierò con informazioni tecniche su dove, come o quando puoi ottenere un ⟦Eye of Sulfuras=Occhio di Sulfuras⟧. Di sicuro lo scoprirai da te. Firma soltanto questo contratto qui, così il nostro accordo sarà vincolante e il nostro affare sarà concluso.", "." },
  ["f1414d06e968fe2f"] = { "Ti prego, ricorda ciò che ti abbiamo mostrato...", "." },
  ["f141f2dfb42775d9"] = { "Mojka, coprimi! Ho delle faccende da sbrigare.", "." },
  ["f143867b27e22d57"] = { "<Stupido/Stupida> {race}! Il clan ⟦Blackrock=Roccianera⟧ danzerà sulla tua tomba!", "." },
  ["f14b8ad0163285b1"] = { "Il ⟦Icewing Bunker=Fortilizio di Algidala⟧ sorveglia il passo tra il territorio dell'⟦Alliance=Alleanza⟧ e il ⟦Field of Strife=Pian della Discordia⟧.\n\nNon è controllato da nessuna delle due fazioni.", "." },
  ["f14c03d52b7b02c7"] = { "%s emette un bubolio minaccioso.", "." },
  ["f154288a6666262f"] = { "Allora non dobbiamo perdere altro tempo. Lo stormo cromatico è pronto?", "." },
  ["f1572a2f6d9cf7d1"] = { "Ti do il benvenuto al Blue Recluse, dove gli appassionati di magia si riuniscono per scaricare la tensione. Non in senso letterale, s'intende. Cosa ti porto, <signore/signora>?", "." },
  ["f15b694ea5d67c9a"] = { "Sì! Mi è passata! Mi è pass... ohi, mi gira la testa, troppo in fretta in piedi!", "." },
  ["f15c09909333fb21"] = { "Relara... sei sveglia?", "." },
  ["f15cde226c42b8dc"] = { "%s fa avanti e indietro nervosamente.", "." },
  ["f1668418307b1264"] = { "Shelby Stoneflint custodisce un bel po' di famigli per i cacciatori del posto. La trovi vicino alla ⟦Thunderbrew Distillery=Distilleria Birratuono⟧, se ti serve qualcuno che badi al tuo famiglio.", "." },
  ["f168dac79190cc3a"] = { "Il momento che C'thun aveva atteso con tanta pazienza era finalmente giunto. I suoi figli avevano passato migliaia di anni a costruire un esercito capace di vendicarsi su tutta Kalimdor, e ora il premio era alla loro portata.", "." },
  ["f175c3a46a0429d2"] = { "Seguimi, <buon/buona> <Paladino/Paladina>. Ti preparerò la bardatura più in fretta di quanto riesca a scolarmi una birra scura nanica. Mmmm... birra scura.", "." },
  ["f18971b7b7671c3f"] = { "%s ti guarda con aria interrogativa. Forse dovresti esaminarlo?", "." },
  ["f1972d6897f5e0f3"] = { "Soccombete allo sguardo, mortali!", "." },
  ["f1a48741ceca8e3a"] = { "Ammirate la potenza dell'⟦Alliance=Alleanza⟧! La temibile signora Onyxia pende dagli archi! Che il grido di battaglia dell'ammazzadraghi vi risollevi gli animi!", "." },
  ["f1a7b2e33b9d5338"] = { "Forse torneranno in sé... e fuggiranno più veloci che possono.", "." },
  ["f1a9151b2b0bdf62"] = { "Dovrò concentrare le mie energie su questo coltello. Così facendo, dovrei cogliere alcune delle impressioni psichiche più forti che vi sono legate.", "." },
  ["f1ad8bd1667ad0dd"] = { "Ora rispondimi, {name}:\n\nQuale creatura divenne il Re dei Lich prima di diffondere la piaga in tutta Lordaeron?", "." },
  ["f1ae70d2fc1b8267"] = { "Non sei ancora abbastanza potente, {class}. Circola.", "." },
  ["f1b1d22e74c10a5e"] = { "I pugni di un Orco sono già un'arma potente, quindi perché non aggiungervi lame o borchie d'acciaio massiccio? Ora i pugni con cui domo i lupi delle pianure posso usarli anche per frantumare l'armatura dei miei nemici.", "." },
  ["f1b28244009c3c10"] = { "Speriamo bene!", "." },
  ["f1b3ae718a3b8755"] = { "Finalmente libertà! Ora lavoriamo insieme per salvare mio fratello, Sothos!", "." },
  ["f1b59d1c04023848"] = { "Capisco. Sembra estremamente pericoloso, ma la situazione sembra richiedere che si corrano dei rischi.\n\nMolto bene, l'High Order fornirà aiuto. Ti prego, informa Valennia che può contare su di noi per questa battaglia.", "." },
  ["f1bff04f1da10f46"] = { "Fatti sotto e combatti, mezza calzetta!", "." },
  ["f1da185098ddccf5"] = { "Salute, {class}: sono un ufficiale degli encomi e opero per conto di ⟦Ironforge=Forgiardente⟧. Il mio compito è assistere gli avventurieri che hanno ricevuto Anelli d'Encomio dell'⟦Alliance=Alleanza⟧.\n\nAccetto anelli in quantità diverse, ma lo scambio più vantaggioso per te è consegnarne dieci alla volta. Quando mi consegnerai gli anelli, registrerò le tue gesta nei nostri archivi. Così otterrai la riconoscenza di ⟦Ironforge=Forgiardente⟧ per il tuo impegno e il tuo servizio.", "." },
  ["f1e045956b225ca5"] = { "E c'è pure la Sbronzaforte! Sia lodata la Luce! Morivo di sete!", "." },
  ["f1ff16fc72e71c0e"] = { "Vattene, mortale. Non sei <degno/degna> della mia conoscenza.", "." },
})
